UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Với phái đẹp yêu đồng hồ, dây đeo không chỉ là phụ kiện thay thế mà còn là điểm nhấn thẩm mỹ, thể hiện gu tinh tế và cá tính riêng. Một sợi dây phù hợp có thể khiến chiếc đồng hồ trở nên thanh lịch, sang trọng và cuốn hút hơn ngay từ cổ tay.\"},{\"type\":\"paragraph\",\"html\":\"Dây Đồng Hồ Nữ Da Bê Epsom phong cách Hermes là lựa chọn lý tưởng cho những ai yêu sự tối giản, tinh tế nhưng vẫn đậm chất thời trang cao cấp.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Chất Liệu Da Bê Epsom Cao Cấp</strong>\"},{\"type\":\"paragraph\",\"html\":\"Da bê Epsom là dòng da cao cấp thường được sử dụng trong các sản phẩm xa xỉ của Hermes nhờ độ bền và tính thẩm mỹ vượt trội.\"},{\"type\":\"paragraph\",\"html\":\"Bề mặt da ép vân mịn, đều và sắc nét, giữ form tốt theo thời gian\"},{\"type\":\"paragraph\",\"html\":\"Ít trầy xước, không nhăn gãy, phù hợp sử dụng hằng ngày\"},{\"type\":\"paragraph\",\"html\":\"Da nhẹ, cứng vừa phải nhưng vẫn êm tay, không gây khó chịu khi đeo lâu\"},{\"type\":\"paragraph\",\"html\":\"Màu Cream trang nhã – dễ phối đồ, tôn da tay và mang lại cảm giác sang trọng, nữ tính\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết Kế Thủ Công Tinh Tế</strong>\"},{\"type\":\"paragraph\",\"html\":\"Dáng dây Hermes thanh mảnh, gọn gàng – đặc trưng cho cổ tay nữ\"},{\"type\":\"paragraph\",\"html\":\"Cắt da chuẩn kích thước lug, độ dài dây cân đối theo tay người đeo\"},{\"type\":\"paragraph\",\"html\":\"May chắc chắn, đường chỉ đều, tinh tế\"},{\"type\":\"paragraph\",\"html\":\"Bo mép mài tròn và sơn cạnh nhiều lớp – mềm mại, không cấn tay\"},{\"type\":\"paragraph\",\"html\":\"Lót trong bằng da thật, hạn chế thấm mồ hôi, tăng độ bền\"},{\"type\":\"paragraph\",\"html\":\"Từng chi tiết đều được hoàn thiện cẩn thận để đảm bảo tính thẩm mỹ và sự thoải mái khi sử dụng.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Phù Hợp Với Nhiều Dòng Đồng Hồ Nữ</strong>\"},{\"type\":\"paragraph\",\"html\":\"Đồng hồ nữ cổ điển, dress watch, thời trang\"},{\"type\":\"paragraph\",\"html\":\"Phối đẹp với mặt tròn, mặt vuông, mặt nhỏ hoặc mỏng\"},{\"type\":\"paragraph\",\"html\":\"Có thể dùng cho đồng hồ cơ, quartz hoặc Apple Watch (khi chọn đúng size)\"},{\"type\":\"paragraph\",\"html\":\"Dây dễ phối cùng váy, áo công sở, trang phục thường ngày hoặc phong cách thanh lịch tối giản.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành Cho Ai?</strong>\"},{\"type\":\"paragraph\",\"html\":\"Nữ giới yêu thích phong cách thanh lịch, tối giản kiểu Pháp\"},{\"type\":\"paragraph\",\"html\":\"Người muốn thay dây để “làm mới” chiếc đồng hồ yêu thích\"},{\"type\":\"paragraph\",\"html\":\"Người yêu đồ da thật, ưu tiên chất lượng và độ bền\"},{\"type\":\"paragraph\",\"html\":\"Phù hợp làm quà tặng tinh tế cho bạn gái, vợ hoặc người thân\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Vì Sao Nên Chọn Dây Đồng Hồ Nữ Da Bê Epsom?</strong>\"},{\"type\":\"paragraph\",\"html\":\"Da bê Epsom cao cấp – bền đẹp, giữ form tốt\"},{\"type\":\"paragraph\",\"html\":\"Thiết kế thanh mảnh, nữ tính, dễ đeo\"},{\"type\":\"paragraph\",\"html\":\"Màu kem sang trọng – không lỗi mốt\"},{\"type\":\"paragraph\",\"html\":\"Hoàn thiện tỉ mỉ, phù hợp sử dụng lâu dài\"},{\"type\":\"paragraph\",\"html\":\"Tôn cổ tay và nâng tầm tổng thể chiếc đồng hồ\"},{\"type\":\"paragraph\",\"html\":\"Dây Đồng Hồ Nữ Da Bê Epsom tại\"},{\"type\":\"paragraph\",\"html\":\"Koi Leather\"},{\"type\":\"paragraph\",\"html\":\"không chỉ là phụ kiện – mà là chi tiết nhỏ tạo nên sự khác biệt lớn. Thanh lịch, tinh tế và nhẹ nhàng, sợi dây dành cho những cô gái yêu sự tối giản nhưng vẫn chú trọng chất lượng và gu thẩm mỹ.\"},{\"type\":\"heading\",\"level\":3,\"html\":\"<strong>Liên hệ để đặt làm &amp; tư vấn</strong>\"}]}"'::jsonb WHERE id='be7cca8b-81c0-4bdf-89c8-4701be72f0d2'; -- day-da-ong-ho-hermes-da-be-epsom-cream
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"<strong>Túi Da Nữ Celine – Da Swift – Black</strong> là mẫu túi nữ được ưa chuộng bởi phom dáng mềm mại, thiết kế tối giản nhưng mang tính thời trang cao. Phiên bản thủ công từ <a href=\\\"https://koileather.com/\\\"><strong>Koi Leather</strong></a>, sử dụng chất liệu da bê Swift màu Black, mang lại cảm giác mềm, mịn, chạm tay là mê – lý tưởng cho những ai yêu phong cách cổ điển hiện đại.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Swift – Mịn mượt, nhẹ tay, mềm mại tự nhiên</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da bê Swift có đặc trưng bề mặt trơn, không vân, độ mịn như lụa\",\"level\":0},{\"html\":\"Màu Black lên ánh tự nhiên, sắc đen sâu, không bóng loáng nhưng có độ phản sáng sang trọng\",\"level\":0},{\"html\":\"Chất da mềm, đổ nhẹ – giúp túi lên form mềm mại đúng tinh thần thiết kế Celine\",\"level\":0},{\"html\":\"Dễ chăm sóc, không nứt gãy – dù sử dụng thường xuyên\",\"level\":0},{\"html\":\"Càng dùng càng lên độ bóng patina nhẹ – cho hiệu ứng sang, thanh lịch hơn theo thời gian\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Swift là loại da sinh ra để tôn vinh thiết kế mềm – không gồng, không phô trương, chỉ đơn giản là cuốn hút.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế Celine – Nhẹ nhàng, đơn giản nhưng đầy khí chất</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Dáng túi mềm, thân túi hơi thắt nhẹ về miệng, tạo phom nữ tính\",\"level\":0},{\"html\":\"Nắp gập bản lớn – dễ mở nhưng vẫn giữ dáng tổng thể hài hòa\",\"level\":0},{\"html\":\"Quai cầm tay bo cong nhẹ – tỉ lệ vừa phải, cầm tay hoặc đeo vai đều đẹp\",\"level\":0},{\"html\":\"Phần dây đeo chéo có thể tháo rời – phù hợp khi cần linh hoạt phong cách\",\"level\":0},{\"html\":\"Bên trong túi rộng, có thể đựng ví dài, điện thoại, sổ tay, mỹ phẩm\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Không cần nhiều chi tiết – chỉ cần đúng chất liệu và tỉ lệ, Celine đã là lựa chọn hoàn hảo cho người có gu.\"},{\"type\":\"paragraph\",\"html\":\"<strong>Xem thêm: <a href=\\\"https://koileather.com/dich-vu-lam-tui-da-theo-yeu-cau/\\\">DỊCH VỤ LÀM TÚI DA THEO YÊU CẦU</a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thủ công tại Koi Leather – Mềm từ chất liệu, mượt từ kỹ thuật</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da Swift được chọn theo từng tấm mịn, không lồi lõm, bề mặt đều màu\",\"level\":0},{\"html\":\"Cắt da, ráp túi, xử lý mép và may tay hoàn toàn thủ công tại xưởng Koi Leather\",\"level\":0},{\"html\":\"Mép da mài cong đều, phủ sơn cạnh nhiều lớp – không gắt, không gãy\",\"level\":0},{\"html\":\"May tay bằng chỉ sáp cao cấp – đều, chắc, mảnh, tăng độ tinh tế cho form mềm\",\"level\":0},{\"html\":\"Nội thất túi có thể tùy chọn lót da lộn, vải canvas hoặc khắc thông điệp riêng bên trong\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Thủ công tại Koi Leather không chỉ là kỹ thuật – đó là cách chúng tôi làm từng chi tiết trở nên có hồn.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu phong cách cổ điển tinh giản – nữ tính, không rườm rà\",\"level\":0},{\"html\":\"Ai cần một chiếc túi mang đi làm, đi họp, dạo phố hay dùng trong sự kiện nhẹ\",\"level\":0},{\"html\":\"Phù hợp mọi lứa tuổi – từ sinh viên, người đi làm đến phụ nữ thành đạt\",\"level\":0},{\"html\":\"Là món quà hoàn hảo cho người phụ nữ yêu thời trang thực thụ\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Vì sao nên chọn Celine Bag từ Koi Leather?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da Swift nhập khẩu – mịn, mềm, bền đẹp theo thời gian\",\"level\":0},{\"html\":\"Dáng túi nữ tính – dễ phối đồ, không lỗi mốt\",\"level\":0},{\"html\":\"Hoàn thiện thủ công – từ đường may, bo mép đến lót trong\",\"level\":0},{\"html\":\"Cá nhân hóa được dây đeo, charm, khắc tên, phối nội thất\",\"level\":0},{\"html\":\"Phối cùng ví dài, cardholder, bao kính, tag vali đồng bộ\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"<strong>Túi Da Nữ Celine – Da Swift – Black</strong> là sự kết hợp giữa đường nét cổ điển và kỹ thuật thủ công hiện đại – tối giản nhưng sang trọng, mềm mại nhưng sắc nét, phù hợp với người phụ nữ có gu và yêu những điều tinh tế.\"}]}"'::jsonb WHERE id='17197bde-b3d7-45e6-b9ad-7dca63c63ae8'; -- tui-da-nu-celine-da-swift-black
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"<strong>Versace WatchStraps – Da Kỳ Đà – Blue</strong> được nhà <strong><a href=\\\"https://koileather.com/\\\">KOI Leather</a> </strong>chế tác 100% thủ công, là lựa chọn dành cho những ai yêu thích phong cách thời trang táo bạo và cá tính đặc trưng của Versace. Được chế tác từ <strong>da kỳ đà tự nhiên</strong>, dây sở hữu bề mặt vảy nhỏ đều, kết cấu chắc chắn cùng sắc Blue nổi bật, tạo điểm nhấn mạnh mẽ cho cổ tay.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Kỳ Đà tự nhiên – Kết cấu vảy đặc trưng</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Sử dụng <strong>da kỳ đà thật</strong>, tuyển chọn kỹ lưỡng\",\"level\":0},{\"html\":\"Bề mặt vảy nhỏ, đều và sắc nét, mang dấu ấn riêng biệt\",\"level\":0},{\"html\":\"Kết cấu da bền chắc, phù hợp sử dụng lâu dài\",\"level\":0},{\"html\":\"Mỗi dây mang nét độc bản tự nhiên, không trùng lặp\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Điểm nhấn thị giác nổi bật trên cổ tay</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Bề mặt vảy da tạo hiệu ứng ánh nhìn mạnh mẽ\",\"level\":0},{\"html\":\"Sắc Blue thu hút, dễ nhận diện từ cái nhìn đầu tiên\",\"level\":0},{\"html\":\"Giúp đồng hồ Versace trở nên nổi bật hơn\",\"level\":0},{\"html\":\"Phù hợp với người yêu phong cách thời trang cá tính\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Phong cách Versace – Táo bạo và thời thượng</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Thể hiện tinh thần fashion-forward đặc trưng\",\"level\":0},{\"html\":\"Phù hợp với outfit hiện đại, cá tính\",\"level\":0},{\"html\":\"Tạo dấu ấn riêng cho người đeo\",\"level\":0},{\"html\":\"Không trộn lẫn với các phong cách cổ điển\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Xem thêm bộ sưu tập<a href=\\\"https://koileather.com/day-da-dong-ho/\\\"><strong> dây da đồng hồ</strong></a> đang được yêu thích tại KOI Leather để lựa chọn phong cách phù hợp nhất.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Tính tương thích và độ hoàn thiện</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Form dây được tinh chỉnh theo đồng hồ Versace\",\"level\":0},{\"html\":\"Lắp đặt dễ dàng, chắc chắn\",\"level\":0},{\"html\":\"Giữ form ổn định trong quá trình sử dụng\",\"level\":0},{\"html\":\"Đảm bảo tính thẩm mỹ tổng thể\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Phụ kiện dành cho người yêu thời trang cao cấp</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Không chỉ là dây thay thế mà là điểm nhấn phong cách\",\"level\":0},{\"html\":\"Phù hợp cho cả đi làm, dạo phố hay sự kiện\",\"level\":0},{\"html\":\"Lựa chọn lý tưởng cho người theo đuổi hình ảnh khác biệt\",\"level\":0}]}]}"'::jsonb WHERE id='7dce935c-d6fe-471e-9512-ddec6462a88e'; -- versace-watchstraps-da-ky-a-blue
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"<strong>Thắt lưng Montblance da Epsom</strong> luôn nằm trong danh sách ưu tiên của những quý ông yêu thích sự tinh tế và sang trọng. Chất liệu da bò dập vân Epsom với bề mặt đặc trưng mang đến vẻ cứng cáp, sạch sẽ và sắc nét trong từng chi tiết. Tông đen cổ điển giúp chiếc <strong>dây nịt Montblanc</strong> trở nên dễ phối đồ, phù hợp với cả môi trường công sở lẫn các buổi gặp gỡ trang trọng.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Epsom – Bền, cứng form và sang trọng</strong>\"},{\"type\":\"paragraph\",\"html\":\"Da Epsom là chất liệu lý tưởng để chế tác <strong>thắt lưng Montblanc da thật</strong> nhờ vào độ cứng form tự nhiên và khả năng chống trầy xước vượt trội. Bề mặt da có vân nổi sắc nét, tạo cảm giác sang trọng và bền đẹp khi sử dụng. Ưu điểm chống thấm nhẹ và dễ vệ sinh giúp chiếc thắt lưng luôn giữ được vẻ ngoài chuẩn chỉnh theo thời gian.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Chống trầy, chống thấm nhẹ\",\"level\":0},{\"html\":\"Giữ form tốt, không gãy nếp\",\"level\":0},{\"html\":\"Bề mặt vân sang trọng, tinh tế\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Những đặc tính này khiến <strong>dây nịt da Epsom</strong> trở thành lựa chọn đáng đầu tư cho các quý ông chuộng sự bền bỉ và chỉnh chu.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Tay nghề thủ công tại Koi Leather</strong>\"},{\"type\":\"paragraph\",\"html\":\"Mỗi chiếc <strong>thắt lưng Montblanc da Epsom</strong> tại Koi Leather được chế tác 100% thủ công bởi đội ngũ thợ lành nghề có nhiều năm kinh nghiệm. Từ việc cắt da, xử lý mép cạnh đến khâu tay đều được thực hiện tỉ mỉ, mang lại độ bền cao và vẻ đẹp hài hòa cho sản phẩm.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Đường cắt sắc nét, tỉ lệ cân đối\",\"level\":0},{\"html\":\"Khâu tay chắc chắn, mũi chỉ đều\",\"level\":0},{\"html\":\"Mép cạnh xử lý thủ công, không lộ keo\",\"level\":0},{\"html\":\"Hỗ trợ khắc tên hoặc logo cá nhân\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Nhờ sự đầu tư trong từng công đoạn, sản phẩm nổi bật hơn nhiều so với các dòng <strong>thắt lưng nam thủ công</strong> phổ thông trên thị trường.\"},{\"type\":\"quote\",\"html\":\"<strong>Xem thêm: <a href=\\\"https://koileather.com/dinh-vu-do-va-cat-day-lung-chuyen-nghiep/\\\">DỊCH VỤ ĐO CẮT VÀ SỬA CHỮA DÂY THẮT LƯNG CHUYÊN NGHIỆP</a></strong> <strong>Tham khảo: <a href=\\\"https://koileather.com/dat-lam-that-lung-theo-yeu-cau-koi-leather/\\\">Đặt Làm Thắt Lưng Theo Yêu Cầu – Koi Leather</a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế tinh giản – Nam tính</strong>\"},{\"type\":\"paragraph\",\"html\":\"Thiết kế của chiếc <strong>thắt lưng Montblanc</strong> hướng đến sự tinh giản và sang trọng. Dây thắt lưng giữ form tốt, kết hợp cùng khóa kim hoặc khóa lật cao cấp, phù hợp với nhiều phong cách khác nhau.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Phối hợp hoàn hảo với quần tây, kaki và jeans\",\"level\":0},{\"html\":\"Khóa kim/khóa lật trơn mượt, chống gỉ\",\"level\":0},{\"html\":\"Dây chắc chắn, không bong tróc theo thời gian\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Nhờ thiết kế tối ưu, sản phẩm dễ dàng trở thành một trong những <strong>thắt lưng nam cao cấp</strong> được yêu thích nhất.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"paragraph\",\"html\":\"<strong>Thắt lưng Montblanc da Epsom</strong> là lựa chọn dành cho những ai đề cao sự chỉnh chu và phong thái chuyên nghiệp. Sản phẩm phù hợp cho doanh nhân, nhân viên văn phòng, người thường xuyên gặp gỡ đối tác hoặc những ai muốn thể hiện gu thẩm mỹ tinh tế.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu phong cách tối giản – sang trọng\",\"level\":0},{\"html\":\"Người cần phụ kiện bền bỉ dùng hằng ngày\",\"level\":0},{\"html\":\"Người coi trọng hình ảnh cá nhân\",\"level\":0},{\"html\":\"Người tìm một chiếc <strong>dây nịt nam sang trọng</strong> dễ phối\",\"level\":0}]},{\"type\":\"quote\",\"html\":\"<strong>Xem thêm: <a href=\\\"https://koileather.com/san-pham/do-da-thu-cong-cao-cap-danh-cho-nam/day-lung-cho-nam/\\\">Các sản phẩm thắt lưng da nam khác tại đây</a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Lý do nên chọn Koi Leather</strong>\"},{\"type\":\"paragraph\",\"html\":\"Koi Leather không chỉ cung cấp một chiếc thắt lưng, mà còn mang đến sản phẩm chứa đựng tinh thần thủ công và sự đầu tư trong từng chi tiết.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da thật cao cấp, tuyển chọn kỹ\",\"level\":0},{\"html\":\"Hoàn thiện 100% thủ công\",\"level\":0},{\"html\":\"Thiết kế hiện đại, tinh giản, dễ phối\",\"level\":0},{\"html\":\"Sản phẩm bền, lên màu đẹp theo thời gian\",\"level\":0},{\"html\":\"Dịch vụ khắc tên – cá nhân hóa theo yêu cầu\",\"level\":0},{\"html\":\"Bảo hành và hỗ trợ lâu dài\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Sở hữu một chiếc <strong>thắt lưng Montblanc da Epsom</strong> từ <a href=\\\"https://koileather.com/\\\"><strong>Koi Leather</strong></a> nghĩa là bạn đang chọn một phụ kiện đẹp, bền và thể hiện phong cách một cách tinh tế nhất.\"}]}"'::jsonb WHERE id='4bc3b151-73a2-4b2b-9e5f-1d7b508e0d03'; -- that-lung-montblance-da-epsom-black
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Tối giản nhưng nổi bật theo cách rất riêng, <strong>Loewe Hammock Hobo Bag – Da Togo – Navy</strong> thiết kế bởi <strong><a href=\\\"https://koileather.com/\\\">KOI Leather</a></strong> gây ấn tượng ngay từ cái nhìn đầu tiên với phom dáng mềm rủ tự nhiên và gam màu xanh Navy sang trọng. Chất da Togo hạt mịn tạo độ bóng nhẹ và cảm giác chạm mềm tay, cho tổng thể chiếc túi vừa hiện đại vừa thanh lịch. Thiết kế gọn gàng cùng khóa kéo kim loại tinh tế giúp chiếc túi trở thành một lựa chọn lý tưởng cho phong cách hằng ngày.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Chất liệu cao cấp</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"<strong>Da Togo thật 100%</strong> với bề mặt hạt mịn, mềm mại nhưng vẫn giữ phom rất tốt.\",\"level\":0},{\"html\":\"Kết cấu da chống xước, chịu lực cao – phù hợp dùng hằng ngày.\",\"level\":0},{\"html\":\"Đường may tỉ mỉ, chắc chắn, thể hiện đúng tinh thần thủ công đặc trưng.\",\"level\":0},{\"html\":\"Khóa kéo kim loại ánh vàng, tạo điểm nhấn sang trọng và bền theo thời gian.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Tối giản mà tiện lợi</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"<strong>Ngăn chính rộng rãi</strong> giúp sắp xếp ví, điện thoại, mỹ phẩm và các vật dụng cần thiết mỗi ngày.\",\"level\":0},{\"html\":\"<strong>Dây đeo đôi linh hoạt</strong>: một dây xách tay và một dây dài để đeo vai/đeo chéo, phù hợp nhiều phong cách.\",\"level\":0},{\"html\":\"Thiết kế <strong>nhẹ, mềm</strong>, mang lâu vẫn thoải mái.\",\"level\":0},{\"html\":\"Phom túi thu gọn gàng, dễ mang khi đi làm, dạo phố hoặc các buổi hẹn nhẹ nhàng.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Xem thêm các mẫu thiết kế ví dành cho nữ được thiết kế riêng bởi KOI Leather <strong><a href=\\\"https://koileather.com/san-pham/cac-san-pham-do-da-cao-cap-danh-cho-phu-nu/vi-da-cho-nu/\\\">TẠI ĐÂY</a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế tinh giản nhưng giàu điểm nhấn</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Dáng hobo mềm giúp chiếc túi ôm nhẹ theo cơ thể, tạo sự tự nhiên khi đeo.\",\"level\":0},{\"html\":\"Đường bo cong hai bên tạo cảm giác thanh thoát, phù hợp mọi dáng người.\",\"level\":0},{\"html\":\"Chi tiết thắt nút ở hai đầu dây đeo mang hơi thở thủ công tinh tế – đặc trưng của phong cách hiện đại.\",\"level\":0},{\"html\":\"Màu Navy trầm sang giúp chiếc túi trở nên hài hòa với cả phong cách công sở lẫn trang phục dạo phố.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu vẻ đẹp <strong>tinh tế, nhẹ nhàng nhưng vẫn nổi bật</strong>.\",\"level\":0},{\"html\":\"Khách hàng tìm một chiếc túi <strong>dễ phối đồ</strong>, dùng được nhiều dịp.\",\"level\":0},{\"html\":\"Người muốn đầu tư vào một chiếc túi <strong>bền – sang – ít lỗi trend</strong>.\",\"level\":0},{\"html\":\"Những ai yêu thích chất da Togo mềm, đẹp và lên màu rất “ăn ảnh.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Loewe Hammock <strong>Hobo Bag – Da Togo – Navy</strong> mang đến sự kết hợp tinh tế giữa chất liệu bền đẹp và thiết kế tiện dụng, trở thành điểm nhấn hoàn hảo cho phong cách mỗi ngày của bạn.\"}]}"'::jsonb WHERE id='d933d31b-4a58-4599-97c3-8b1c98098a14'; -- loewe-hammock-hobo-bag-da-togo-navy
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"<strong>Túi Tote Longchamp – Da Bò – Nâu Chocolate</strong>\"},{\"type\":\"paragraph\",\"html\":\"Lấy cảm hứng từ vẻ đẹp tối giản nhưng đầy tinh tế, <strong>Túi Tote Longchamp – Da Bò – Nâu Chocolate</strong> mang đến gam nâu trầm ấm sang trọng, dễ phối cùng nhiều phong cách thường ngày. Được tái hiện hoàn toàn từ <strong>da bò nguyên tấm vân Togo cao cấp</strong>, sản phẩm sở hữu bề mặt hạt nổi tự nhiên mềm mại, tạo cảm giác cao cấp và bền đẹp theo thời gian.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Vẻ Đẹp Thủ Công Tinh Tế</strong>\"},{\"type\":\"paragraph\",\"html\":\"Thiết kế giữ trọn tinh thần biểu tượng với <strong>nắp gập cài nút bấm</strong>, <strong>khóa kéo chắc chắn</strong> cùng <strong>phụ kiện kim loại bạc sáng bóng</strong> tinh tế. Phần <strong>quai xách dài may ống tròn</strong> cầm chắc tay, thuận tiện để <strong>đeo vai hoặc xách tay</strong> trong nhiều hoàn cảnh sử dụng.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết Kế Màu Theo Yêu Cầu – Cá Nhân Hoá Phong Cách Của Bạn</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"KOI Leather hỗ trợ đặt làm theo màu sắc bạn mong muốn\",\"level\":0},{\"html\":\"Mỗi chiếc túi được làm thủ công theo đơn, đảm bảo đúng màu – đúng chất liệu – đúng form.\",\"level\":0},{\"html\":\"Thích hợp cho khách muốn sở hữu một chiếc túi “có một không hai”, phù hợp tủ đồ hoặc phong cách riêng<br> | <strong>Xem thêm</strong> bộ sưu tập <u><u><a href=\\\"https://koileather.com/san-pham/do-da-thu-cong-cao-cap-danh-cho-nam/vi-da-cho-nam/\\\"><strong>ví da nam</strong></a></u></u> và <u><u><a href=\\\"https://koileather.com/san-pham/cac-san-pham-do-da-cao-cap-danh-cho-phu-nu/vi-da-cho-nu/\\\"><strong>ví da nữ</strong> </a></u></u>để có thêm nhiều gợi ý phụ kiện đồng điệu.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành Cho Ai?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu thích thiết kế nhỏ gọn, hiện đại và dễ phối đồ.\",\"level\":0},{\"html\":\"Khách hàng muốn một chiếc túi da thật bền đẹp, sang trọng nhưng không quá cầu kỳ.\",\"level\":0},{\"html\":\"Những ai muốn <strong>đặt màu riêng</strong> để tạo dấu ấn cá nhân hoặc tặng người thân theo tone màu họ yêu thích.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Một chiếc túi được làm bằng sự tỉ mỉ và cảm hứng cá nhân, <strong>Túi Chub – Da Bò – Pink</strong> chắc chắn sẽ trở thành điểm nhấn đầy cuốn hút trong phong cách thường ngày của bạn.\"},{\"type\":\"heading\",\"level\":3,\"html\":\"<strong>Liên hệ để đặt làm &amp; tư vấn</strong>\"},{\"type\":\"paragraph\",\"html\":\"Hotline: 0901 678 999\"},{\"type\":\"paragraph\",\"html\":\"Email: koi.leather19@gmail.com\"}]}"'::jsonb WHERE id='5cba4be7-22d1-45f8-908e-6b44f720293f'; -- tui-tote-longchamp-da-bo-van-togo-nau-chocolate
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"<strong>Ví Nữ Da – Da Carvia – Black</strong> là thiết kế mang hơi thở cổ điển của dòng ví Chanel mini, sử dụng chất liệu da Carvia vân hạt cao cấp, đường chần quả trám nổi bật và khóa kim loại vàng đầy khí chất. Thiết kế nhỏ gọn nhưng tiện dụng – thích hợp để đựng tiền, thẻ, giấy tờ nhỏ, phù hợp dùng hằng ngày hoặc khi đi tiệc.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Carvia – Vân hạt nổi, giữ phom tốt và dễ sử dụng</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da Carvia thật – vân hạt sần tự nhiên, không bóng, cảm giác sang và chắc tay\",\"level\":0},{\"html\":\"Màu Black – màu đen cổ điển, dễ phối đồ, không lỗi mốt\",\"level\":0},{\"html\":\"Giữ phom tốt – không nhão, không gãy, lý tưởng cho thiết kế ví nhỏ chần bông\",\"level\":0},{\"html\":\"Chống trầy nhẹ – phù hợp sử dụng mỗi ngày, bỏ túi áo hoặc túi xách\",\"level\":0},{\"html\":\"Dễ lau sạch – chống bám bẩn bề mặt tốt hơn so với da trơn\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Da Carvia là chất liệu lý tưởng để kết hợp đường may chần nổi – vừa giữ được form ví, vừa tạo khối rõ nét.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế ví nữ nhỏ – Thanh lịch, tiện dụng, nữ tính</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Dáng ví ngang nhỏ – vừa lòng bàn tay, dễ bỏ túi, sang như clutch mini\",\"level\":0},{\"html\":\"Chần bông quả trám toàn mặt – tạo hiệu ứng thị giác mềm mại, đầy đặn\",\"level\":0},{\"html\":\"Nắp gập nhẹ với khoá kim loại vàng – điểm nhấn nổi bật\",\"level\":0},{\"html\":\"Bên trong chia ngăn – đựng thẻ, tiền, giấy tờ nhỏ, son mini hoặc chìa khoá\",\"level\":0},{\"html\":\"Đường viền bo mềm, không cấn – tạo cảm giác dễ chịu khi sử dụng lâu\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Thiết kế phù hợp cho người phụ nữ tinh tế – yêu sự gọn gàng, thanh lịch và nữ tính.\"},{\"type\":\"quote\",\"html\":\"<strong>Xem thêm: <a href=\\\"https://koileather.com/lam-vi-da-theo-yeu-cau/\\\">Đặt làm ví da handmade theo yêu cầu </a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Tay Nghề Thủ công tại Koi Leather – Gọn gàng, chắc chắn, hoàn thiện tinh xảo</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Từng miếng da được cắt tỉ lệ chính xác – đảm bảo đối xứng khi chần quả trám\",\"level\":0},{\"html\":\"Chần tay nổi khối, may đều – tạo hiệu ứng mềm mà không xẹp\",\"level\":0},{\"html\":\"Chỉ sáp cao cấp – chắc chắn, đều tay, có thể chọn tone chỉ tương phản hoặc tiệp màu\",\"level\":0},{\"html\":\"Nắp ví cứng nhẹ – giữ phom đẹp, viền mép mài và sơn kỹ lưỡng\",\"level\":0},{\"html\":\"Có thể khắc tên, cá nhân hóa màu chỉ hoặc phối da theo yêu cầu\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Đường may chần bông yêu cầu kỹ thuật khắt khe – từng ô đều, cân và nổi khối – là minh chứng cho tay nghề thủ công tại Koi Leather.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu ví nhỏ – tối giản nhưng cần sự sang trọng và thanh lịch\",\"level\":0},{\"html\":\"Ai thích phong cách cổ điển – đen, kim loại, đường chần và kiểu dáng truyền thống\",\"level\":0},{\"html\":\"Phù hợp dùng mỗi ngày, đi chơi, đi tiệc hoặc kết hợp cùng túi xách lớn\",\"level\":0},{\"html\":\"Là món quà hoàn hảo cho mẹ, chị gái, bạn gái hoặc bản thân\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Vì sao nên chọn Ví Nữ Da – Da Carvia từ Koi Leather?</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Da thật – mềm, giữ phom, sang và dễ dùng\",\"level\":0},{\"html\":\"Thiết kế chần bông – đẹp, cá tính nhưng vẫn rất nữ tính\",\"level\":0},{\"html\":\"May tay thủ công – chắc chắn, tỉ mỉ, cá nhân hóa cao\",\"level\":0},{\"html\":\"Dễ phối đồ, dùng được ở mọi hoàn cảnh\",\"level\":0},{\"html\":\"<strong>Có thể cá nhân hóa: chọn chỉ, phối màu, khắc tên, logo</strong>\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"<strong>Ví Nữ Da – Da Carvia – Black</strong> là sự kết hợp tinh tế giữa cổ điển và hiện đại – vừa gọn nhẹ, tiện dụng nhưng vẫn có nét sang và chất riêng. Dành cho những người phụ nữ yêu sự chỉn chu, tinh tế – và hiểu rằng một chiếc ví nhỏ, hoàn thiện tốt là điều không thể thiếu trong phong cách hàng ngày.\"}]}"'::jsonb WHERE id='063603dc-9446-48b4-a296-91015b965760'; -- vi-nu-da-da-carvia-black
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Trong cuộc sống hiện đại, khi mọi thứ ngày càng tối giản và tiện dụng, ví đựng thẻ (card holder) trở thành món phụ kiện “nhỏ mà có võ” – vừa gọn gàng, tiện lợi, vừa thể hiện gu sống chỉn chu và thẩm mỹ cá tính. Với chất liệu da Epsom cao cấp, màu cam rực rỡ (Orange) và kỹ thuật hoàn thiện thủ công tại xưởng, <strong>Card Holder Ví Đựng Thẻ – Da Epsom – Orange</strong> của <a href=\\\"https://koileather.com/\\\"><strong>Koi Leather</strong></a> là lựa chọn lý tưởng cho những ai đang tìm kiếm sự tinh tế và năng động trong từng chi tiết.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Epsom – Bền, nhẹ, sang và dễ vệ sinh</strong>\"},{\"type\":\"paragraph\",\"html\":\"Epsom leather là loại da bê được xử lý ép vân bằng nhiệt, thường dùng trong các dòng túi và phụ kiện của Hermès. Khi áp dụng cho ví đựng thẻ, chất liệu này mang lại những ưu điểm nổi bật:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Vân nhỏ, đều, chống trầy xước và ít bám vết bẩn, rất phù hợp cho sản phẩm sử dụng hàng ngày.\",\"level\":0},{\"html\":\"Giữ form tốt, nhẹ và cứng cáp, giúp ví không bị biến dạng dù bỏ vào túi chật.\",\"level\":0},{\"html\":\"Lên màu cực kỳ sắc nét – đặc biệt là với các tông sáng như cam.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Màu Orange – Sắc cam cá tính, trẻ trung và nổi bật</strong>\"},{\"type\":\"paragraph\",\"html\":\"Màu cam trong dòng da Epsom của Koi Leather mang phong cách cam Hermes – rực rỡ nhưng không “chói”, đủ nổi bật để tạo điểm nhấn nhưng vẫn giữ được sự thanh lịch.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Thể hiện sự năng động, quyết đoán, tích cực.\",\"level\":0},{\"html\":\"Dễ phối với các tông trung tính như trắng, be, navy hoặc đen.\",\"level\":0},{\"html\":\"Là lựa chọn lý tưởng cho những ai yêu thích phong cách sáng tạo, cá nhân hóa và không ngại nổi bật.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế tối giản – Gọn nhẹ nhưng vẫn đủ công năng</strong>\"},{\"type\":\"paragraph\",\"html\":\"Ví được thiết kế siêu mỏng, nhỏ gọn, tối ưu cho những ai muốn:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Mang theo 4–6 thẻ (ATM, thẻ ID, namecard, membership…).\",\"level\":0},{\"html\":\"Có ngăn chính ở giữa để đựng tiền mặt gấp gọn hoặc danh thiếp.\",\"level\":0},{\"html\":\"Bỏ vừa túi quần, túi áo, clutch hoặc túi mini mà không gây cộm.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Form ví tối giản phù hợp với cả nam lẫn nữ, đặc biệt là người thường xuyên di chuyển hoặc làm việc văn phòng.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Chế tác thủ công – Tỉ mỉ từ đường kim đến mép da</strong>\"},{\"type\":\"paragraph\",\"html\":\"Sản phẩm được hoàn thiện 100% thủ công tại xưởng Koi Leather:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"May tay bằng chỉ sáp cao cấp, từng mũi chắc chắn, đẹp và đều.\",\"level\":0},{\"html\":\"Cạnh da được bo và sơn nhiều lớp, chống bong tróc và cho cảm giác mượt khi cầm.\",\"level\":0},{\"html\":\"Có thể khắc tên, logo, phối chỉ màu hoặc đổi màu lót trong theo yêu cầu – biến mỗi chiếc card holder thành một món phụ kiện độc bản.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"paragraph\",\"html\":\"Card Holder – Da Epsom – Orange phù hợp với:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu thích thiết kế tối giản, nhẹ gọn, sử dụng linh hoạt.\",\"level\":0},{\"html\":\"Những ai theo đuổi phong cách sáng tạo, trẻ trung và khác biệt.\",\"level\":0},{\"html\":\"Người làm việc trong môi trường hiện đại: freelancer, startup, tài chính, công nghệ, thời trang, thiết kế…\",\"level\":0},{\"html\":\"Là món quà nhỏ nhưng “chất” cho bạn bè, đồng nghiệp, người thân hoặc chính mình.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"<strong>Card Holder – Da Epsom – Orange</strong> không chỉ là ví đựng thẻ – mà là một mảnh ghép tinh tế trong phong cách sống của người hiện đại. Từ màu sắc nổi bật, chất liệu cao cấp đến độ hoàn thiện thủ công, sản phẩm thể hiện tư duy sống gọn, đẹp và có gu – đúng chuẩn những người luôn hướng đến sự cá nhân hóa đích thực.\"}]}"'::jsonb WHERE id='53d07e1b-ab8a-4faf-a66c-8f842ab4e927'; -- card-holder-vi-ung-the-da-epsom-orange
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Với những ai sở hữu đồng hồ cao cấp, đặc biệt là đồng hồ cơ, việc bảo vệ chúng khi di chuyển là điều không thể xem nhẹ. Nhưng tại <strong><a href=\\\"https://koileather.com/\\\">Koi Leather</a>,</strong> bạn không chỉ được bảo vệ – mà còn được nâng tầm đẳng cấp với chiếc <strong>Travel Watch Case – Da Clemence – Orange:</strong> một phụ kiện thủ công, bền bỉ và đầy phong cách.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Clemence – Mềm mại, bền bỉ và sang trọng vượt thời gian</strong>\"},{\"type\":\"paragraph\",\"html\":\"Clemence leather là dòng da bê cao cấp, nổi bật với:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Vân tự nhiên, mềm mại nhưng có độ đứng nhẹ, giúp hộp giữ form tốt nhưng không cứng nhắc.\",\"level\":0},{\"html\":\"Chống trầy nhẹ, ít thấm nước và dễ vệ sinh, lý tưởng để mang đi công tác hoặc du lịch.\",\"level\":0},{\"html\":\"Càng dùng càng đẹp – phát triển patina bóng mờ tự nhiên theo thời gian, tôn lên giá trị sử dụng lâu dài.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Với Travel Watch Case, da Clemence giúp tạo nên cảm giác cầm nắm dễ chịu, mềm tay nhưng vẫn đủ chắc chắn để bảo vệ vật phẩm bên trong.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Màu Orange – Rực rỡ, cá tính và thời thượng</strong>\"},{\"type\":\"paragraph\",\"html\":\"Orange – sắc cam Hermès đặc trưng – là màu thể hiện:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Tinh thần phóng khoáng, sáng tạo và nổi bật có gu, thường thấy ở những người yêu thời trang và sống năng động.\",\"level\":0},{\"html\":\"Tương phản đẹp mắt với các tông màu đồng hồ như bạc, đen, trắng hoặc nâu.\",\"level\":0},{\"html\":\"Là điểm nhấn độc đáo trong hành lý của bạn – dễ nhận diện, khó nhầm lẫn, vừa tiện vừa đẹp.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế tối ưu – Gọn gàng, bảo vệ tối đa</strong>\"},{\"type\":\"paragraph\",\"html\":\"Travel Watch Case được thiết kế chuyên biệt cho nhu cầu di chuyển:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"1 hoặc 2 khoang chứa, phù hợp cho đồng hồ dây kim loại hoặc dây da, cả nam và nữ.\",\"level\":0},{\"html\":\"Lót da hoặc nỉ cao cấp bên trong, tránh trầy xước và va đập.\",\"level\":0},{\"html\":\"Nút bấm, nam châm hoặc khóa kéo giấu kín, đảm bảo thẩm mỹ và an toàn trong hành lý.\",\"level\":0},{\"html\":\"Form nhỏ gọn, dễ bỏ túi, balo hoặc vali carry-on – phù hợp đi công tác, du lịch hoặc dùng làm hộp quà tặng sang trọng.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Chế tác thủ công – Mỗi chiếc là một sản phẩm độc bản</strong>\"},{\"type\":\"paragraph\",\"html\":\"Được thực hiện 100% thủ công tại xưởng Koi Leather, với tiêu chuẩn cao cấp:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Cắt da, chọn vân và xử lý mép bằng tay, giữ vân da tự nhiên mượt mà.\",\"level\":0},{\"html\":\"May tay bằng chỉ sáp cao cấp, chắc chắn, bền và đều đặn hơn so với may máy.\",\"level\":0},{\"html\":\"Bo mép và sơn cạnh nhiều lớp thủ công, giúp bề mặt mượt, không bong tróc, không cấn.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Khách hàng có thể tùy chỉnh:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Khắc tên, logo hoặc ký hiệu cá nhân\",\"level\":0},{\"html\":\"Chọn màu chỉ, phối da 2 tone (VD: cam – nâu, cam – kem…)\",\"level\":0},{\"html\":\"Tăng thêm khoang đồng hồ, hoặc biến tấu thành hộp đa năng (đựng vòng tay, nhẫn, tai nghe…)\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"paragraph\",\"html\":\"Travel Watch Case – Da Clemence – Orange là lựa chọn lý tưởng cho:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người sở hữu đồng hồ cao cấp (cơ, tự động, vintage, quartz…) và cần bảo quản khi di chuyển.\",\"level\":0},{\"html\":\"Tín đồ thời trang tối giản có điểm nhấn, yêu phụ kiện da thật độc bản.\",\"level\":0},{\"html\":\"Người đang tìm món quà tinh tế – có chiều sâu – mang tính cá nhân hóa cao.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"<strong>Travel Watch Case – Da Clemence – Orange</strong> là món phụ kiện thể hiện gu sống chỉn chu, biết yêu và bảo vệ những giá trị bền lâu – đặc biệt là với đồng hồ, món đồ mang tính biểu tượng. Kết hợp giữa chất da mềm cao cấp, sắc cam thời thượng và thiết kế chuẩn chỉnh, đây là một chiếc hộp không chỉ đựng đồng hồ – mà còn đựng cả phong cách riêng biệt của bạn.\"}]}"'::jsonb WHERE id='f340473c-3535-42c1-a9f1-97d3196beb99'; -- travel-watch-case-da-clemence-orange
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Một chiếc bìa hộ chiếu không chỉ giúp bảo vệ giấy tờ quan trọng – mà còn là tuyên ngôn cá tính của người yêu xê dịch và yêu cái đẹp. Sản phẩm <strong>Passport Cover – Da Epsom – Oldlace x Orange</strong> của <a href=\\\"https://koileather.com/\\\"><strong>Koi Leather</strong></a> mang trong mình tinh thần ấy: độc đáo – tinh gọn – khác biệt, được chế tác thủ công tỉ mỉ từ da bê Epsom cao cấp phối màu thời trang.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Epsom – Chất liệu bền đẹp theo từng dặm bay</strong>\"},{\"type\":\"paragraph\",\"html\":\"Epsom leather là dòng da bê được dập vân bằng nhiệt, nổi tiếng với độ bền và tính thẩm mỹ cao:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Vân nhỏ, đều và chống trầy xước tốt, khó bị bám bẩn khi sử dụng thường xuyên.\",\"level\":0},{\"html\":\"Chất da nhẹ, cứng cáp, giữ form tốt, rất phù hợp để làm bìa hộ chiếu – thường bị cong hoặc mòn mép sau nhiều lần cất ra – vào.\",\"level\":0},{\"html\":\"Lên màu rõ nét, sang trọng và rất “ăn” phối màu, lý tưởng để tạo nên các thiết kế sáng tạo như bản phối Oldlace x Orange.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Phối màu Oldlace x Orange – Tinh tế bên ngoài, nổi bật bên trong</strong>\"},{\"type\":\"paragraph\",\"html\":\"Sự kết hợp giữa hai gam màu đối lập mang đến hiệu ứng thị giác cực kỳ ấn tượng:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Oldlace (trắng kem ngà) – nhẹ nhàng, trung tính, tinh khôi và tối giản, tạo cảm giác thư giãn, hiện đại.\",\"level\":0},{\"html\":\"Orange (cam Hermes) – rực rỡ, trẻ trung, nổi bật và mang tinh thần phóng khoáng của người thích dịch chuyển.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Phối màu này không chỉ độc đáo, mà còn mang tính “dual personality” – trang nhã bên ngoài, tươi sáng bên trong – như chính những người yêu tự do nhưng sống rất có gu.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế tối ưu – Gọn gàng và tiện dụng khi qua cửa khẩu</strong>\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Kích thước chuẩn hộ chiếu quốc tế, ôm vừa vặn, không thừa mép.\",\"level\":0},{\"html\":\"2 ngăn bên trong để cố định hộ chiếu, cùng khe phụ để đựng boarding pass, vé máy bay, thẻ tiêm, hoặc card.\",\"level\":0},{\"html\":\"Form đứng, không phồng cộm, dễ dàng cất vào túi áo, túi xách tay hoặc clutch du lịch.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Chế tác thủ công – Mỗi chi tiết đều có tâm</strong>\"},{\"type\":\"paragraph\",\"html\":\"Từng sản phẩm được làm 100% thủ công tại xưởng Koi Leather, bởi nghệ nhân nhiều năm kinh nghiệm:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"May tay bằng chỉ sáp cao cấp, chắc chắn, đều và có thể cá nhân hóa màu chỉ theo yêu cầu.\",\"level\":0},{\"html\":\"Cạnh da được bo, sơn thủ công nhiều lớp, không bong tróc, mượt tay khi sử dụng lâu dài.\",\"level\":0},{\"html\":\"Có thể khắc tên, chữ viết tay, biểu tượng hoặc logo cá nhân, biến mỗi chiếc thành một passport cover độc bản.\",\"level\":0}]},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Dành cho ai?</strong>\"},{\"type\":\"paragraph\",\"html\":\"Passport Cover – Da Epsom – Oldlace x Orange là món phụ kiện lý tưởng dành cho:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Người yêu thích phụ kiện thủ công nhỏ gọn nhưng có chiều sâu thẩm mỹ.\",\"level\":0},{\"html\":\"Ai thường xuyên đi du lịch, công tác và muốn hộ chiếu được bảo vệ tốt – đồng thời mang theo phong cách riêng biệt.\",\"level\":0},{\"html\":\"Người tìm kiếm món quà tinh tế, hữu dụng và mang dấu ấn cá nhân, phù hợp cho bạn bè, người thân, đồng nghiệp quốc tế.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"<strong>Passport Cover – Da Epsom – Oldlace x Orange</strong> không chỉ giúp bạn giữ gìn giấy tờ quan trọng, mà còn thể hiện rõ cá tính, phong cách sống và gu thẩm mỹ của người sành đồ da. Một phụ kiện nhỏ, nhưng là cửa ngõ dẫn bạn đến những hành trình đẹp hơn – gọn gàng hơn – có gu hơn.\"}]}"'::jsonb WHERE id='e8c6caaf-4259-4d1f-87da-bbd496f32305'; -- passport-cover-da-epsom-oldlace-x-orange
UPDATE koi_free_style.koi_products SET "descriptionBlocks"='"{\"blocks\":[{\"type\":\"paragraph\",\"html\":\"Trong thế giới phụ kiện cao cấp, một chiếc túi xách không chỉ để mang theo vật dụng – mà còn là tuyên ngôn về phong cách sống, gu thẩm mỹ và cá tính. <strong>Tiffany Bag – Da Epi – Aqua</strong> từ <a href=\\\"https://koileather.com/\\\"><strong>Koi Leather</strong></a> là sự kết hợp hài hòa giữa phom dáng cổ điển, màu sắc trẻ trung và chất liệu da Epi sang trọng, dành riêng cho những quý cô hiện đại, yêu sự khác biệt và luôn sẵn sàng nổi bật theo cách riêng.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Da Epi – Biểu tượng của sự bền bỉ và thời trang</strong>\"},{\"type\":\"paragraph\",\"html\":\"Da Epi là loại da bò được dập vân nổi đặc trưng theo chiều ngang – từng được Louis Vuitton chọn làm chất liệu chủ lực cho nhiều dòng túi kinh điển. Đặc tính nổi bật:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Chống trầy xước và chống nước cực tốt nhờ vào lớp phủ bảo vệ bên ngoài.\",\"level\":0},{\"html\":\"Bề mặt vân gỗ nổi nhẹ, sang trọng nhưng rất bền, không dễ bị cũ theo thời gian.\",\"level\":0},{\"html\":\"Giữ form cực kỳ ổn định, đặc biệt phù hợp với các mẫu túi có thiết kế cứng cáp như Tiffany Bag.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Màu Aqua (xanh ngọc biển) mang lại cảm giác tươi mới, mát mẻ và đầy năng lượng – thích hợp với mùa hè, các chuyến du lịch hoặc đơn giản là để làm mới phong cách hằng ngày.\"},{\"type\":\"paragraph\",\"html\":\"<strong>Xem thêm: <a href=\\\"https://koileather.com/dich-vu-lam-tui-da-theo-yeu-cau/\\\">DỊCH VỤ LÀM TÚI DA THEO YÊU CẦU</a></strong>\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thiết kế Tiffany Bag – Cổ điển, gọn gàng và thanh thoát</strong>\"},{\"type\":\"paragraph\",\"html\":\"Lấy cảm hứng từ phong cách ladylike vintage, Tiffany Bag có phom dáng hình thang đứng, với phần nắp gập mềm mại, tay cầm bo tròn thanh lịch.\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Kích thước vừa phải, có thể đựng điện thoại, ví nhỏ, mỹ phẩm cá nhân.\",\"level\":0},{\"html\":\"Nắp túi gập có khóa ẩn, dễ thao tác, giữ sự liền mạch và thẩm mỹ tổng thể.\",\"level\":0},{\"html\":\"Tay cầm chắc chắn, dễ cầm tay hoặc khoác tay, và đi kèm dây đeo dài tháo rời để có thể đeo chéo hoặc đeo vai.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Tiffany Bag là kiểu túi dễ kết hợp với váy, suit, sơ mi hoặc trang phục casual chic, mang đến sự thanh lịch trong mọi hoàn cảnh.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Thủ công tinh tế – Từng đường may là một dấu ấn</strong>\"},{\"type\":\"paragraph\",\"html\":\"Sản phẩm được hoàn thiện 100% thủ công tại xưởng Koi Leather, đảm bảo tính cá nhân và độ bền vượt trội:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"May tay bằng chỉ sáp cao cấp, chắc chắn và tăng tính thẩm mỹ.\",\"level\":0},{\"html\":\"Cạnh túi sơn viền nhiều lớp, không bong tróc sau thời gian dài sử dụng.\",\"level\":0},{\"html\":\"Nội thất được lót vải canvas hoặc da mềm, bố trí ngăn phụ tiện dụng.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Khách hàng có thể <strong>đặt khắc tên, ký hiệu hoặc thay đổi chi tiết theo yêu cầu</strong>, tăng tính cá nhân hóa và độc bản.\"},{\"type\":\"heading\",\"level\":2,\"html\":\"<strong>Phụ kiện hoàn hảo cho phụ nữ yêu phong cách sống tinh tế</strong>\"},{\"type\":\"paragraph\",\"html\":\"<strong>Tiffany Bag – Da Epi – Aqua</strong> là chiếc túi lý tưởng cho:\"},{\"type\":\"list\",\"ordered\":false,\"items\":[{\"html\":\"Những người yêu phong cách nữ tính, thanh lịch, hiện đại.\",\"level\":0},{\"html\":\"Dự tiệc nhẹ, café, công sở hoặc các buổi họp mặt cuối tuần.\",\"level\":0},{\"html\":\"Làm quà tặng cao cấp cho sinh nhật, lễ tốt nghiệp, kỷ niệm hoặc các dịp đặc biệt.\",\"level\":0}]},{\"type\":\"paragraph\",\"html\":\"Không chỉ là một chiếc túi, Tiffany Bag còn là lời khẳng định gu thẩm mỹ và cá tính riêng biệt.\"},{\"type\":\"paragraph\",\"html\":\"Nếu bạn đang tìm kiếm một chiếc túi vừa thanh lịch, vừa trẻ trung, vừa có độ bền cao thì <strong>Tiffany Bag – Da Epi – Aqua</strong> chính là món phụ kiện xứng đáng có mặt trong tủ đồ. Vẻ đẹp vượt thời gian, thiết kế thủ công chuẩn chỉnh và gam màu thời thượng – tất cả hòa quyện tạo nên một sản phẩm “chạm vào là yêu – dùng mãi không chán”.\"}]}"'::jsonb WHERE id='262011b7-57d5-482a-a988-add8e6ff016a'; -- tiffany-bag-da-epi-aqua
